pub fn find(name: []const u8) ?System {
    var low: usize = 0;
    var high: usize = systems.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        switch (@import("std").mem.order(u8, systems[middle].id, name)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return systems[middle],
        }
    }
    return null;
}

