pub fn findOverride(locale: []const u8, system: []const u8) ?Override {
    var low: usize = 0;
    var high: usize = overrides.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const entry = overrides[middle];
        const order = std.mem.order(u8, entry.locale, locale);
        if (order == .lt or (order == .eq and std.mem.order(u8, entry.system, system) == .lt)) {
            low = middle + 1;
        } else if (order == .gt or std.mem.order(u8, entry.system, system) == .gt) {
            high = middle;
        } else {
            return entry;
        }
    }
    return null;
}
